/* Layout for this component's own nodes.
   These were per-node `styles` overrides. Past a certain number of them in
   one document the browser stops matching the compiled
   [data-bz-node="x"][data-bz-node] rules — some apply and some silently do
   not — so the same declarations live here instead, where they hold. See the
   note in the commit message; this is a platform bug worth fixing upstream.
   ------------------------------------------------------------------------- */
[data-bz-node="type-slider-band"]{padding-top:96px;padding-bottom:88px;padding-left:48px;padding-right:48px;margin-top:40px;margin-bottom:40px;overflow:hidden}
[data-bz-node="type-slider-stage"]{max-width:1280px;margin-left:auto;margin-right:auto;position:relative;height:460px}
@media (max-width: 640px){
[data-bz-node="type-slider-band"]{padding-top:56px;padding-bottom:64px;padding-left:0px;padding-right:0px}
[data-bz-node="type-slider-stage"]{height:auto}
}

/* ---------------------------------------------------------- TYPE SLIDER ---
   A coverflow: no `carousel` option expresses cards placed by signed distance
   with per-step scale, opacity and stacking, so the placement is scripted (see
   this component's js). Everything the script does is gated behind
   `.is-staged`, which it adds itself — so the rule below this comment is what
   the Design canvas and the first paint get: a real in-flow scroll rail with
   all five cards present and selectable, which is also the handoff's own phone
   fallback. Nothing is invisible or stacked before the script runs.
   ------------------------------------------------------------------------- */

[data-bz-node="type-slider-band"] { text-align: center; }
[data-bz-node="type-slider-band"] .bz-block { padding-block: 0; }
[data-bz-node="type-slider-title"] h2 { font-size: 32px; line-height: 1.6; color: #fff; margin: 0 0 56px; }

/* Un-staged: a scroll rail. */
[data-bz-node="type-slider-stage"]:not(.is-staged) {
  display: flex;
  gap: 14px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: auto;
}
[data-bz-node="type-slider-stage"]:not(.is-staged) > .bz-col {
  flex: 0 0 340px;
  scroll-snap-align: start;
  position: relative;
}

/* Staged: the coverflow. The script sets transform, opacity and z-index. */
[data-bz-node="type-slider-stage"].is-staged { display: block; }
[data-bz-node="type-slider-stage"].is-staged > .bz-col {
  position: absolute;
  top: 50%;
  left: 50%;
  margin-left: -170px;
  margin-top: -210px;
  transition: transform 0.4s ease, opacity 0.4s ease;
  cursor: pointer;
}
[data-bz-node="type-slider-stage"].is-staged > .bz-col.is-active { cursor: default; }

/* The card itself, in both states. */
[data-bz-node="type-slider-stage"] > .bz-col {
  width: 340px;
  height: 420px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  padding: 28px 0 0;
  overflow: hidden;
}
/* The photograph is a layer, and the gradient over it deepens on the active
   card — the handoff's two dim levels, as CSS rather than as scripted style. */
[data-bz-node="type-slider-stage"] > .bz-col::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(20, 20, 20, 0.15), rgba(20, 20, 20, 0.5));
  z-index: 1;
}
[data-bz-node="type-slider-stage"] > .bz-col.is-active::after {
  background: linear-gradient(180deg, rgba(20, 20, 20, 0.15), rgba(20, 20, 20, 0.72));
}
[data-bz-node="type-slider-stage"] .bz-block--image {
  position: absolute;
  inset: 0;
  z-index: 0;
  padding: 0;
}
[data-bz-node="type-slider-stage"] .bz-block--image .bz-container,
[data-bz-node="type-slider-stage"] .bz-block--image figure { height: 100%; }
[data-bz-node="type-slider-stage"] .bz-block--image img {
  width: 100%; height: 100%;
  object-fit: cover; object-position: center;
  display: block;
}

[data-bz-node="type-slider-stage"] .bz-block--text { position: relative; z-index: 2; width: 100%; }
[data-bz-node="type-slider-stage"] .bz-block--text .bz-text { max-width: none; }
[data-bz-node="type-slider-stage"] .bz-block--text p {
  font: 800 var(--text-base, 15px) / 1.6 var(--font-heading);
  color: #B5B5B5;
  padding: 0 20px;
  margin: 0;
}
[data-bz-node="type-slider-stage"] > .bz-col.is-active .bz-block--text p { font-size: 26px; color: #fff; }

[data-bz-node="type-slider-stage"] .bz-block--buttons {
  position: absolute;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 2;
  width: 150px;
}
[data-bz-node="type-slider-stage"] .bz-block--buttons .bz-btns { justify-content: center; }
[data-bz-node="type-slider-stage"] .bz-block--buttons .bz-btn {
  width: 150px;
  /* 10px here is intentional even in the hard-edged theme, matching the
     featured-listing button — the handoff calls this out. */
  border-radius: 10px;
}
/* Only the active card shows its CTA once the coverflow is staged. */
[data-bz-node="type-slider-stage"].is-staged > .bz-col:not(.is-active) .bz-block--buttons {
  display: none;
}

.ss-slider-nav { display: flex; gap: 10px; justify-content: center; margin-top: 24px; }
.ss-slider-nav button {
  width: 40px; height: 40px;
  border-radius: 50%;
  border: 1px solid #444;
  background: none;
  color: #fff;
  cursor: pointer;
  font-size: 16px;
  font-family: var(--font-body);
}
.ss-slider-nav button:hover { border-color: #666; }

@media (max-width: 640px) {
  [data-bz-node="type-slider-title"] h2 { font-size: 26px; padding-inline: 20px; }
  /* The handoff drops the depth effect and the arrows on a phone. */
  [data-bz-node="type-slider-stage"].is-staged { display: flex; }
  .ss-slider-nav { display: none; }
  [data-bz-node="type-slider-stage"] > .bz-col { flex: 0 0 82vw; }
}

js:
/* The coverflow. A `carousel` behaviour moves a rail; this places every card
   by its signed distance from the active one and drives scale, opacity and
   stacking from that one number — which no behaviour option expresses, so it
   is written out here, scoped to this component's own nodes.

   The staged layout is switched on by the `is-staged` class this adds, so the
   un-staged rail in the CSS is what the Design canvas and the first paint
   render. */
(function () {
  var stage = document.querySelector('[data-bz-node="type-slider-stage"]');
  if (!stage) return;

  var cards = Array.prototype.slice.call(stage.children);
  if (cards.length < 2) return;

  var CARD_OFFSET = 270;              // px between neighbouring cards
  var SCALES = [1, 0.78, 0.6];
  var OPACITIES = [1, 0.6, 0.32];
  var active = Math.min(2, cards.length - 1);

  function render() {
    cards.forEach(function (card, i) {
      var dist = i - active;
      // Take the shorter way round, so the set behaves as a loop.
      if (dist > cards.length / 2) dist -= cards.length;
      if (dist < -cards.length / 2) dist += cards.length;
      var abs = Math.min(Math.abs(dist), 2);

      card.style.transform = 'translateX(' + dist * CARD_OFFSET + 'px) scale(' + SCALES[abs] + ')';
      card.style.opacity = OPACITIES[abs];
      card.style.zIndex = String(10 - abs);
      card.classList.toggle('is-active', abs === 0);
    });
  }

  stage.addEventListener('click', function (event) {
    // A click on the active card's CTA is a link; leave it alone.
    if (event.target.closest('.bz-block--buttons')) return;
    var card = event.target.closest('[data-bz-type="column"]');
    if (!card || card.parentNode !== stage) return;
    var i = cards.indexOf(card);
    if (i > -1 && i !== active) { active = i; render(); }
  });

  var prev = document.querySelector('[data-ss-type-prev]');
  var next = document.querySelector('[data-ss-type-next]');
  if (prev) prev.addEventListener('click', function () {
    active = (active - 1 + cards.length) % cards.length;
    render();
  });
  if (next) next.addEventListener('click', function () {
    active = (active + 1) % cards.length;
    render();
  });

  stage.classList.add('is-staged');
  render();
})();
